select pe.transportista, count(pe.id_pedido) as pedidos, sum(pe.entrega_tarde) as entregas_tarde, round(sum(pe.entrega_tarde)*100.0/count(pe.id_pedido),2) as porcentaje_tarde from PedidosRaw pe group by pe.transportista order by porcentaje_tarde desc;
select pe.prioridad, count(pe.id_pedido) as pedidos, sum(pe.entrega_tarde) as entregas_tarde, round(sum(pe.entrega_tarde)*100.0/COUNT(pe.id_pedido),2) as porcentaje_tardes from PedidosRaw pe group by pe.prioridad order by porcentaje_tardes desc;
select pr.categoria, count(pe.id_pedido) as pedidos, sum(pe.entrega_tarde) as entregas_tardias, round(sum(pe.entrega_tarde)*100.0/count(pe.id_pedido),2) as porcentaje_tardes from ProductosRaw pr inner join PedidosRaw pe on pr.id_producto = pe.id_producto group by pr.categoria order by porcentaje_tardes desc;
select pe.canal, count(pe.id_pedido) as pedidos, sum(pe.entrega_tarde) as entregas_tarde, round(sum(pe.entrega_tarde)*100.0/COUNT(pe.id_pedido),2) as porcentaje_tardes from PedidosRaw pe group by pe.canal order by porcentaje_tardes desc;
select c.provincia, avg(pe.distancia_km) as distancia_media, sum(pe.entrega_tarde) as entregas_tardias, round(sum(pe.entrega_tarde)*100.0/count(pe.id_pedido),2) as porcentaje_tardes from ClientesRaw c inner join PedidosRaw pe on c.id_cliente  = pe.id_cliente group by c.provincia order by porcentaje_tardes desc;
select case when pe.stock_al_pedido<10 then "Stock Bajo" when pe.stock_al_pedido<20 then "Stock Medio" else "Stock Alto" end as Nivel_Stock, sum(pe.entrega_tarde) as Entregas_tarde, round(sum(pe.entrega_tarde)*100.0/count(pe.id_pedido),2) as Porcentaje_Tardes from PedidosRaw pe group by Nivel_Stock order by Porcentaje_Tardes desc;
select pe.transportista, round(sum(pe.entrega_tarde)*100.0/COUNT(pe.id_pedido),2) as porcentaje_tardes from PedidosRaw pe group by pe.transportista having porcentaje_tardes >(select avg(porcentaje_tarde) as porcentaje_medio from (select pe.transportista,round(sum(pe.entrega_tarde)*100.0/count(pe.id_pedido),2) as porcentaje_tarde from PedidosRaw pe group by pe.transportista order by porcentaje_tarde desc)) order by porcentaje_tardes desc;
select c.incidencias_previas , sum(pe.entrega_tarde) as entregas_tardias, round(sum(pe.entrega_tarde)*100.0/count(pe.id_pedido),2) as porcentaje_tardes from ClientesRaw c inner join PedidosRaw pe on c.id_cliente  = pe.id_cliente group by c.incidencias_previas  order by porcentaje_tardes desc;